public class InitializationDemonstration {
    static {
        System.out.println("Static block executing: Initialization phase active");
    }

    public static final int CONSTANT_PRIMITIVE = 100; // Compile-time constant, does not trigger initialization
    public static int nonConstant = 200; // Triggers initialization when accessed

    public static void main(String[] args) {
        System.out.println("Main method started");
        // Accessing nonConstant triggers the loading, linking, and initialization of InitializationDemonstration
        int val = InitializationDemonstration.nonConstant;
    }
}
